import type {FC} from 'react';
import React, {memo, useRef} from 'react';

import {TextInput, getConfig} from '@gravity-ui/uikit';

import {useAutoFocus} from '~/src/hooks/useAutoFocus';
import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnTrackerSelect} from '../TrackerSelect.classname';
import {defaultMessages} from '../i18n';

type SearchProps = {
    autoFocus?: boolean;
    value?: string;
    controlRef?: React.RefObject<HTMLInputElement>;
    hasClear?: boolean;
    onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
    onFocus?: (event: React.FocusEvent<HTMLInputElement>) => void;
    placeholder?: string;
    controlProps?: React.HTMLAttributes<HTMLInputElement>;
};

export const Search: FC<SearchProps> = memo(({autoFocus, ...props}: SearchProps = {}) => {
    const searchContainerRef = useRef<HTMLDivElement>(null);

    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    useAutoFocus({
        containerRef: searchContainerRef,
        elementSelector: '.g-text-input__control',
        shouldFocus: autoFocus ?? true,
    });

    return (
        <div className={cnTrackerSelect('search-container')} ref={searchContainerRef}>
            <TextInput
                className={cnTrackerSelect('search')}
                view="clear"
                size="l"
                placeholder={t('search')}
                {...props}
            />
        </div>
    );
});

Search.displayName = 'Search';
